ementTypeCode": {"@listName": "exclusion-grounds-source", "#text": "epo-procurement-document"}}}}, "cac:TenderingProcess": {"cbc:ProcedureCode": {"@listName": "procurement-procedure-type", "#text": "open"}, "cac:ProcessJustification": {"cbc:ProcessReasonCode": {"@listName": "accelerated-procedure", "#text": "false"}}}, "cac:ProcurementProject": {"cbc:Name": {"@languageID": "FRA", "#text": "MISSIONS DE MAITRISE D'OEUVRE POUR LA REALISATION DE TRAVAUX D’ASSAINISSEMENT SUR LES RÉSEAUX ET OUVRAGES  D’EAUX PLUVIALES ET D’EAUX USÉES"}, "cbc:Description": {"@languageID": "FRA", "#text": "Accord-cadre à bons de commandes pour des missions de maîtrise d'oeuvre relatif aux travaux d'assainissement sur les réseaux et ouvrages d'eaux pluviales et d'eaux usées envisagés.

La typologie des travaux concernés sont:
RESEAUX : 
- Les travaux d'extension des réseaux d'assainissement d'eaux usées et/ou d'eaux pluviales ;
- Réhabilitation sans ouverture de tranchée de réseaux d'eaux usées et/ou d'eaux pluviales ;
- Renouvellement de réseaux d'eaux usées et/ou d'eaux pluviales ;
- Etude Hydrauliques du fonctionnement des réseaux (EP/EU).

OUVRAGES : 
- Travaux de gros entretiens et de maintenance sur les ouvrages d'assainissement existants ;
- Travaux de réhabilitation et de modification des ouvrages d'assainissement existants (Poste de refoulement, bassins tampons, poste d'injection, traitement H2S, clapet...) ;
- Travaux de construction ou reconstruction de postes de refoulement (inférieur à 20 000 EH) ;
- Travaux de construction ou reconstruction de petites stations d'épuration (inférieur à 2000 EH)."}, "cbc:ProcurementTypeCode": {"@listName": "contract-nature", "#text": "services"}, "cac:RequestedTenderTotal": {"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efbc:FrameworkMaximumAmount": {"@currencyID": "EUR", "#text": "340000"}}}}}}, "cac:MainCommodityClassification": {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "71250000"}}}, "cac:ProcurementProjectLot": {"cbc:ID": {"@schemeName": "Lot", "#text": "LOT-0001"}, "cac:TenderingTerms": {"cbc:FundingProgramCode": {"@listName": "eu-funded", "#text": "no-eu-funds"}, "cac:CallForTendersDocumentReference": {"cbc:ID": "_DEFAULT_VALUE_CHANGE_ME_", "cbc:DocumentType": "non-restricted-document", "cac:Attachment": {"cac:ExternalReference": {"cbc:URI": "www.marches-securises.fr"}}}, "cac:TendererQualificationRequest": [{"cac:SpecificTendererRequirement": {"cbc:TendererRequirementTypeCode": {"@listName": "selection-criteria-source", "#text": "epo-procurement-document"}}}, {"cbc:CompanyLegalFormCode": {"@listName": "required", "#text": "true"}, "cbc:CompanyLegalForm": {"@languageID": "FRA", "#text": "Groupement conjoint avec mandataire solidaire ou groupement solidaire"}}], "cac:ContractExecutionRequirement": [{"cbc:ExecutionRequirementCode": {"@listName": "reserved-execution", "#text": "no"}}, {"cbc:ExecutionRequirementCode": {"@listName": "einvoicing", "#text": "required"}}, {"cbc:ExecutionRequirementCode": {"@listName": "ecatalog-submission", "#text": "not-allowed"}}], "cac:AwardingTerms": {"cac:AwardingCriterion": {"cac:SubordinateAwardingCriterion": [{"cbc:AwardingCriterionTypeCode": {"@listName": "award-criterion-type", "#text": "price"}, "cbc:Description": {"@languageID": "FRA", "#text": "Prix 55%"}}, {"cbc:AwardingCriterionTypeCode": {"@listName": "award-criterion-type", "#text": "quality"}, "cbc:Description": {"@languageID": "FRA", "#text": "Valeur technique 